package provider

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"strings"
	"time"
)

// Default is what Dummy Run picks for a provider when you name none. This table is the one place the
// defaults live. docs/PROVIDERS.md shows it, generated by go generate ./cmd/dummyrun.
type Default struct {
	// Label is the name shown to people, such as "OpenAI".
	Label string
	// Provider is the --provider value it maps to.
	Provider string
	// Model is the model used when --model is not given.
	Model string
	// Endpoint, Region, APIKeyEnv and ReasoningEffort fill the matching flags when they are not given.
	Endpoint        string
	Region          string
	APIKeyEnv       string
	ReasoningEffort string
	// Trigger says, in words, what makes Dummy Run choose it.
	Trigger string
	// Why is the reason for the model, with the vendor page that names it.
	Why string
}

// The defaults, in the order Detect tries them after Azure.
var (
	DefaultOpenAI = Default{ //nolint:gosec // names of environment variables, not credentials
		Label: "OpenAI", Provider: NameOpenAICompatible, Model: "gpt-6-luna",
		Endpoint: "https://api.openai.com/v1", Region: "global", APIKeyEnv: "OPENAI_API_KEY", ReasoningEffort: "none",
		Trigger: "`OPENAI_API_KEY` is set",
		Why:     "The cheapest GPT-6 model, with function calling and image input. On chat completions it calls tools only with reasoning off, so the default sends `--reasoning-effort none`. [OpenAI models](https://developers.openai.com/api/docs/models/gpt-6-luna)",
	}
	DefaultAnthropic = Default{
		Label: "Anthropic", Provider: NameAnthropic, Model: "claude-haiku-5-5",
		APIKeyEnv: DefaultAnthropicKeyEnv,
		Trigger:   "`ANTHROPIC_API_KEY` is set",
		Why:       "The fastest and cheapest Claude, with tool use and image input. [Anthropic models](https://platform.claude.com/docs/en/about-claude/models/overview)",
	}
	DefaultOllama = Default{
		Label: "Ollama", Provider: NameOpenAICompatible, Model: "gemma4:e4b",
		Endpoint: "http://localhost:11434/v1", Region: "local",
		Trigger: "`OLLAMA_HOST` is set, or Ollama answers on `localhost:11434`",
		Why:     "A local model that lists both tools and vision, so your data stays on your machine. Run `ollama pull gemma4:e4b` once. [Ollama gemma4](https://ollama.com/library/gemma4)",
	}
	DefaultAzure = Default{
		Label: "Azure OpenAI", Provider: NameAzure,
		Trigger: "`DUMMYRUN_AZURE_ENDPOINT` is set",
		Why:     "Deployment names are your own, so there is no default model. Pass `--model` and `--region`.",
	}
)

// Defaults lists every default, in the order Detect tries them.
func Defaults() []Default {
	return []Default{DefaultAzure, DefaultOpenAI, DefaultAnthropic, DefaultOllama}
}

// DefaultModelFor returns the default model for an explicitly named provider, or "" when there is none.
func DefaultModelFor(name string) string {
	if name == NameAnthropic {
		return DefaultAnthropic.Model
	}
	return ""
}

// Choice is what Detect picked.
type Choice struct {
	Default
	// Endpoint overrides the default's, as when OLLAMA_HOST names another machine.
	Endpoint string
	// Found says what Dummy Run saw, such as "OPENAI_API_KEY is set".
	Found string
}

// Summary is the one line printed first in a run: the provider, the model and why.
func (c Choice) Summary(model string) string {
	if model == "" {
		model = c.Model
	}
	return fmt.Sprintf("Using %s %s (%s)", c.Label, model, c.Found)
}

// ErrNoProvider is returned by Detect when nothing points at a model.
var ErrNoProvider = errors.New(`no model provider found. Set one of these, then run the command again:
  export OPENAI_API_KEY=...        an OpenAI key
  export ANTHROPIC_API_KEY=...     an Anthropic key
  ollama pull gemma4:e4b           a local model, with Ollama running
  export DUMMYRUN_AZURE_ENDPOINT=https://<resource>.openai.azure.com   Azure OpenAI, with --model and --region
Or name one with --provider. docs/PROVIDERS.md lists them all`)

// Env is what Detect looks at, so tests can supply their own.
type Env struct {
	Getenv func(string) string
	// Ollama lists the models on the server at base (such as http://localhost:11434), or returns an error
	// when nothing answers. Nil uses OllamaModels.
	Ollama func(ctx context.Context, base string) ([]string, error)
}

// Detect picks a provider from the environment, in this order: Azure OpenAI when DUMMYRUN_AZURE_ENDPOINT is
// set, since only a person who set it up for Dummy Run has it and it was the only default before; then OpenAI,
// then Anthropic, then Ollama.
func Detect(ctx context.Context, env Env) (Choice, error) {
	get := env.Getenv
	if get == nil {
		return Choice{}, errors.New("provider: Detect needs Getenv")
	}
	if v := get("DUMMYRUN_AZURE_ENDPOINT"); v != "" {
		return Choice{Default: DefaultAzure, Endpoint: v, Found: "DUMMYRUN_AZURE_ENDPOINT is set"}, nil
	}
	if get("OPENAI_API_KEY") != "" {
		return Choice{Default: DefaultOpenAI, Endpoint: DefaultOpenAI.Endpoint, Found: "OPENAI_API_KEY is set"}, nil
	}
	if get("ANTHROPIC_API_KEY") != "" {
		return Choice{Default: DefaultAnthropic, Found: "ANTHROPIC_API_KEY is set"}, nil
	}
	list := env.Ollama
	if list == nil {
		list = OllamaModels
	}
	host, explicit := get("OLLAMA_HOST"), true
	if host == "" {
		host, explicit = "localhost:11434", false
	}
	base, err := OllamaBase(host)
	if err != nil {
		return Choice{}, err
	}
	models, err := list(ctx, base)
	if err != nil {
		if explicit {
			return Choice{}, fmt.Errorf("OLLAMA_HOST is %s but nothing answers there (%w). Start Ollama with: ollama serve", host, err)
		}
		return Choice{}, ErrNoProvider
	}
	found := "Ollama answers on " + strings.TrimPrefix(strings.TrimPrefix(base, "http://"), "https://")
	if explicit {
		found = "OLLAMA_HOST is " + host
	}
	c := Choice{Default: DefaultOllama, Endpoint: base + "/v1", Found: found}
	if !HasOllamaModel(models, DefaultOllama.Model) {
		return c, &ModelMissingError{Choice: c, Have: models}
	}
	return c, nil
}

// ModelMissingError means Ollama runs but the default model is not pulled. The Choice is still filled in, so
// a caller that was given --model can go on.
type ModelMissingError struct {
	Choice Choice
	Have   []string
}

func (e *ModelMissingError) Error() string {
	msg := fmt.Sprintf("Ollama is running but has not got %s. Run: ollama pull %s", e.Choice.Model, e.Choice.Model)
	if len(e.Have) > 0 {
		msg += "\nOr pick one you have, as long as it lists tools and vision: --model " + e.Have[0]
	}
	return msg
}

// HasOllamaModel reports whether the list holds name, with or without the ":latest" tag.
func HasOllamaModel(models []string, name string) bool {
	for _, m := range models {
		if m == name || m == name+":latest" || strings.TrimSuffix(m, ":latest") == name {
			return true
		}
	}
	return false
}

// OllamaBase turns an OLLAMA_HOST value into a base URL. Ollama accepts "host", "host:port", ":port",
// "0.0.0.0" and full URLs, with 11434 as the default port.
func OllamaBase(host string) (string, error) {
	h := strings.TrimSpace(host)
	if !strings.Contains(h, "://") {
		h = "http://" + h
	}
	u, err := url.Parse(h)
	if err != nil || u.Host == "" && u.Path == "" {
		return "", fmt.Errorf("OLLAMA_HOST %q is not a host name or URL", host)
	}
	hostname, port := u.Hostname(), u.Port()
	if hostname == "" || hostname == "0.0.0.0" || hostname == "::" {
		hostname = "127.0.0.1"
	}
	if port == "" {
		port = "11434"
	}
	return u.Scheme + "://" + net.JoinHostPort(hostname, port), nil
}

// OllamaModels asks the Ollama server at base which models it holds. It waits one second at most, so a
// machine without Ollama does not stall.
func OllamaModels(ctx context.Context, base string) ([]string, error) {
	ctx, cancel := context.WithTimeout(ctx, time.Second)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, base+"/api/tags", nil)
	if err != nil {
		return nil, err
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer func() { _ = resp.Body.Close() }()
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("answered %s", resp.Status)
	}
	var body struct {
		Models []struct {
			Name string `json:"name"`
		} `json:"models"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
		return nil, fmt.Errorf("not an Ollama answer: %w", err)
	}
	names := make([]string, 0, len(body.Models))
	for _, m := range body.Models {
		names = append(names, m.Name)
	}
	return names, nil
}
